using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using MultiFPS;using MultiFPS.UI;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftCombat;using ROM.Horde;using ROM.Progression;
namespace ROM.UI.Gameplay {
 public enum RiftQuestPinKind { Available, Objective, TurnIn, InProgress }
 public sealed class RiftQuestPinEntry {public string Key,Title,Description,QuestId;public Vector3 World;public RiftQuestPinKind Kind;public int Count=1;public int Priority=>Kind==RiftQuestPinKind.TurnIn?3:Kind==RiftQuestPinKind.Objective?2:Kind==RiftQuestPinKind.InProgress?0:1;}
 // Read-only presentation model: it never accepts, progresses or pays a quest.
 public sealed class RiftQuestPinModel {
  RiftEnemySpawnZone[] zones=Array.Empty<RiftEnemySpawnZone>();RiftCheckpoint[] crystals=Array.Empty<RiftCheckpoint>();float nextScan;
  public List<RiftQuestPinEntry> Build(JournalState state,RiftJournalCatalog catalog,CharacterInstance actor){var result=new List<RiftQuestPinEntry>();if(state==null||!catalog||!actor)return result;if(Time.unscaledTime>=nextScan||zones.Length==0){nextScan=Time.unscaledTime+2;zones=UnityEngine.Object.FindObjectsByType<RiftEnemySpawnZone>(FindObjectsSortMode.None);crystals=UnityEngine.Object.FindObjectsByType<RiftCheckpoint>(FindObjectsSortMode.None);}
   foreach(var npc in RiftVillageNpc.Active.Where(n=>n&&n.gameObject.activeInHierarchy).OrderBy(n=>n.Id,StringComparer.Ordinal)){
    var ready=catalog.Quests.Where(q=>q&&q.TurnIn==npc.Id&&state.Quest(q.Id)?.Status==QuestStatus.Ready).ToArray();var offers=catalog.Quests.Where(q=>q&&q.Giver==npc.Id&&state.Available(q)).ToArray();var active=catalog.Quests.Where(q=>q&&(q.Giver==npc.Id||q.TurnIn==npc.Id)&&state.Quest(q.Id)?.Status==QuestStatus.Active).ToArray();if(ready.Length==0&&offers.Length==0&&active.Length==0)continue;
    string description=(ready.Length>0?"Listas para entregar:\n"+string.Join("\n",ready.Select(q=>"• "+q.Title)):"")+(ready.Length>0&&offers.Length>0?"\n\n":"")+(offers.Length>0?"Disponibles:\n"+string.Join("\n",offers.Select(q=>"• "+q.Title)):"");
    result.Add(new RiftQuestPinEntry{Key="npc:"+npc.Id,World=npc.transform.position,Kind=ready.Length>0?RiftQuestPinKind.TurnIn:offers.Length>0?RiftQuestPinKind.Available:RiftQuestPinKind.InProgress,Title=npc.DisplayName+" · "+(ready.Length>0?"Entregar misiones":offers.Length>0?"Misiones disponibles":"Misiones en curso"),Description=description+(active.Length>0?"\nEn curso:\n"+string.Join("\n",active.Select(q=>q.Title)):""),QuestId=ready.FirstOrDefault()?.Id??offers.FirstOrDefault()?.Id??active[0].Id,Count=ready.Length+offers.Length+active.Length});
   }
   var record=RiftQuestGuidance.Tracked(state);var def=record!=null?catalog.Quest(record.Id):null;if(!def||record.Status!=QuestStatus.Active||def.Objectives==null||!state.PrerequisitesMet(def))return result;int level=ClientFrontend.ClientPlayerInstance?ClientFrontend.ClientPlayerInstance.GetComponent<AbilityController>()?.Level??1:1;
   for(int i=0;i<def.Objectives.Length;i++){var o=def.Objectives[i];if(o==null)continue;int progress=record.Progress!=null&&i<record.Progress.Length?record.Progress[i]:0;if(progress>=o.Required)continue;string baseKey=def.Id+":"+i+":";string description=def.Title+"\n"+o.Label+" · "+progress+" / "+o.Required;
    if(o.Event==RiftProgressEvent.Collect){foreach(var group in RiftQuestCollectible.Active.Where(x=>x&&x.gameObject.activeInHierarchy&&o.Matches(o.Event,x.ItemKey)&&x.Eligible(state,catalog)&&!(record.Seen?.Contains("collect:"+i+":"+x.StableId)??false)).GroupBy(x=>x.StableId)){if(group.Count()!=1)continue;var x=group.First();Add(result,baseKey+x.StableId,x.transform.position,x.DisplayName,description,def.Id);}}
    else if(o.Event==RiftProgressEvent.Talk){foreach(var n in RiftVillageNpc.Active.Where(n=>n&&o.Matches(o.Event,n.Id)&&(!o.Unique||!(record.Seen?.Contains(i+":"+n.Id)??false))))Add(result,baseKey+n.Id,n.transform.position,n.DisplayName,description,def.Id);}
    else if(o.Event==RiftProgressEvent.TrainingHit){foreach(var h in Health.All.Where(h=>h&&h.TrainingTarget&&h.gameObject.activeInHierarchy&&o.Matches(o.Event,"dummy")))Add(result,baseKey+h.GetInstanceID(),h.transform.position,"Entrenamiento",description,def.Id);}
    else if(o.Event==RiftProgressEvent.PotionBought){var npc=RiftVillageNpc.Active.Where(n=>n&&n.Trades).OrderBy(n=>n.Id==def.Giver?0:1).ThenBy(n=>(n.transform.position-actor.transform.position).sqrMagnitude).FirstOrDefault();if(npc)Add(result,baseKey+npc.Id,npc.transform.position,npc.DisplayName+" · Provisiones",description,def.Id);}
    else if(o.Event==RiftProgressEvent.Checkpoint){var matches=crystals.Where(c=>c&&!c.StartingCamp&&o.Matches(o.Event,c.Title)&&(!o.Unique||!(record.Seen?.Contains(i+":"+c.Title)??false))).OrderBy(c=>MinimumLevel(c.Title)<=level+3?0:1).ThenBy(c=>MinimumLevel(c.Title)<=level+3?0:MinimumLevel(c.Title)).ThenBy(c=>(c.transform.position-actor.transform.position).sqrMagnitude).Take(1);foreach(var c in matches)Add(result,baseKey+c.Title,c.transform.position,c.Title+" · Cristal",description,def.Id);}
    else if(o.Event==RiftProgressEvent.Encounter){var world=ROM.Horde.Horde.Instance;if(world&&world.Encounters!=null)foreach(var e in world.Encounters.Where(e=>e&&!e.Cleared&&o.Matches(o.Event,e.Title)).OrderBy(e=>(e.transform.position-actor.transform.position).sqrMagnitude).Take(2))Add(result,baseKey+e.Title,e.transform.position,e.Title,description,def.Id);}
    else if(o.Event==RiftProgressEvent.Kill||o.Event==RiftProgressEvent.MiniBoss){var matches=zones.Where(z=>z&&!z.Cleared&&z.Enemies!=null&&z.Enemies.Any(e=>e.Enemy&&e.Enemy.Team!=actor.Health.Team&&!e.Enemy.IsWildlife&&o.Matches(o.Event,e.Enemy.Id,z.Encounter?z.Encounter.Title:z.Title)&&(o.Event!=RiftProgressEvent.MiniBoss||e.Enemy.IsBoss))).Where(z=>!string.IsNullOrEmpty(o.Filter)||!string.IsNullOrEmpty(o.EncounterFilter)||RiftQuestGuidance.SuitableCombatRange(level,z.MinimumLevel,z.MaximumLevel)).OrderBy(z=>z.MinimumLevel<=level+3?0:1).ThenBy(z=>z.MinimumLevel<=level+3?0:z.MinimumLevel).ThenBy(z=>(z.transform.position-actor.transform.position).sqrMagnitude).Take(string.IsNullOrEmpty(o.EncounterFilter)?3:1);foreach(var z in matches){var points=z.SpawnPoints?.Where(t=>t).ToArray();var pos=points!=null&&points.Length>0?points.Aggregate(Vector3.zero,(v,t)=>v+t.position)/points.Length:z.transform.position;Add(result,baseKey+z.Title,pos,z.Title+" · "+z.LevelRange,description+(z.MinimumLevel>level+3?"\nPeligro: enemigos de nivel superior.":""),def.Id);}}
   }return result;
  }
  int MinimumLevel(string region){var found=zones.Where(z=>z&&z.RegionTitle==region).ToArray();return found.Length>0?found.Min(z=>Mathf.Min(z.MinimumLevel,z.MaximumLevel)):60;}
  static void Add(List<RiftQuestPinEntry> entries,string key,Vector3 world,string title,string description,string quest){entries.Add(new RiftQuestPinEntry{Key=key,World=world,Title=title,Description=description,QuestId=quest,Kind=RiftQuestPinKind.Objective});}
 }
}
